arguments.command:
BASE='http://127.0.0.1:45027/zEgxnBUw9i0='; ISO='isolates/713118720882011'; PATHS='/opt/nothingness/media/01-undercover-49.opus,/opt/nothingness/media/02-undercover-50.opus,/opt/nothingness/media/03-undercover-51.opus,/opt/nothingness/media/04-undercover-52.opus,/opt/nothingness/media/05-undercover-53.opus,/opt/nothingness/media/06-undercover-54.opus,/opt/nothingness/media/07-undercover-44.opus,/opt/nothingness/media/08-undercover-45.opus,/opt/nothingness/media/09-undercover-46.opus,/opt/nothingness/media/10-undercover-47.opus';
set -e;
curl -s "$BASE/ext.nothingness.setQueue?isolateId=$ISO&paths=$PATHS&startIndex=0";
# open settings sheet
curl -s "$BASE/ext.nothingness.openSettingsSheet?isolateId=$ISO";
# enable shuffle by tapping toggle
curl -s "$BASE/ext.nothingness.tapByKey?isolateId=$ISO&key=void-settings-status-shuffle";
# start playback
curl -s "$BASE/ext.nothingness.play?isolateId=$ISO";
# read state
sleep 1;
curl -s "$BASE/ext.nothingness.getPlaybackState?isolateId=$ISO";

